import{_ as t,o as i,c as r,a3 as n,j as o,t as a,a as l}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"Agent 集成","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/knowledge-base/agent-integration.md","filePath":"user-guide/tools/knowledge-base/agent-integration.md","lastUpdated":1784419875000}'),s={name:"user-guide/tools/knowledge-base/agent-integration.md"};function g(d,e,c,u,p,k){return i(),r("div",null,[e[9]||(e[9]=n('<h1 id="agent-集成" tabindex="-1">Agent 集成 <a class="header-anchor" href="#agent-集成" aria-label="Permalink to &quot;Agent 集成&quot;">​</a></h1><p>Knowledge 通过独立的 <code>knowledgeAccess</code> 接入 Agent。配置只保存稳定的资料库 ID 和能力权限；资料库名称、说明、来源数量与可用状态在运行时解析。</p><h2 id="资料访问权限" tabindex="-1">资料访问权限 <a class="header-anchor" href="#资料访问权限" aria-label="Permalink to &quot;资料访问权限&quot;">​</a></h2><p><code>knowledgeAccess</code> 包含：</p><ul><li><code>enabled</code>：是否允许 Agent 使用 Knowledge。</li><li><code>allowedLibraryIds</code>：允许访问的稳定资料库 ID。</li><li><code>allowSearchAll</code>：调用未指定资料库时，是否允许搜索全部已授权库。</li><li><code>allowDocumentRead</code>：是否允许从检索命中继续读取文档局部。</li><li><code>allowResearch</code>：是否允许启动高成本研究任务。</li></ul><p>授权不等于自动查询。Agent 获得权限后，普通消息不会因此增加 Knowledge 检索或 Embedding 调用。</p><h2 id="资料库目录宏" tabindex="-1">资料库目录宏 <a class="header-anchor" href="#资料库目录宏" aria-label="Permalink to &quot;资料库目录宏&quot;">​</a></h2>',7)),o("p",null,[o("code",null,a(d.knowledge_list),1),e[0]||(e[0]=l(" 在用户放置它的预设消息位置展开已授权资料库目录，内容包含稳定 ID、当前名称、说明、来源数量和可用状态。资料库改名后会显示新名称；已删除或暂时不可用的授权不会静默消失。",-1))]),e[10]||(e[10]=n('<p>该宏只列目录，不读取 chunk、不执行检索，也不会在宏缺失时自动选择位置注入。</p><h2 id="主动检索" tabindex="-1">主动检索 <a class="header-anchor" href="#主动检索" aria-label="Permalink to &quot;主动检索&quot;">​</a></h2><p>Knowledge 的检索参数属于单次工具调用，而不是 Agent 授权属性。查询前必须经过当前 Agent 的权限校验；未授权、已删除或不可用的资料库会返回明确错误，不会静默改搜其他库。</p><p>Agent 可以使用三个独立工具：</p><ul><li><code>knowledge.listLibraries</code>：查看当前授权库、来源数量、索引状态和可用检索能力。</li><li><code>knowledge.search</code>：按 <code>auto</code>、<code>keyword</code>、<code>semantic</code> 或 <code>hybrid</code> 快速搜索，支持文档、来源类型和路径过滤，并返回实际策略与降级原因。</li><li><code>knowledge.read</code>：按 chunk、chunk 邻域、heading 或字符范围继续读取证据；必须提供字符预算，且需要 <code>allowDocumentRead</code> 权限。</li></ul><p>多库使用不同 Embedding 空间时会分别生成候选，只在排名层融合；返回值保留原始 score 和 signals，不把不同策略的分数展示为统一准确率。现有上层 Retrieval 组合能力使用同一权限校验，不能绕过 <code>knowledgeAccess</code>。</p><h2 id="聊天中显式引用" tabindex="-1">聊天中显式引用 <a class="header-anchor" href="#聊天中显式引用" aria-label="Permalink to &quot;聊天中显式引用&quot;">​</a></h2><p>聊天输入框工具栏提供独立的 Knowledge 图标，不占用 <code>@</code> 临时模型按钮。打开后可以搜索当前 Agent 已授权的资料库，并选择一个或多个索引已就绪的库。选中项会显示在输入区上方，可以检查稳定 ID 或逐项移除。</p><p>发送后，引用会保存为版本化结构化消息字段，而不是库名文本。系统先显示 <code>knowledge.search</code> 工具事件，再把检索结果交给当前 Agent 回答；事件中保留实际策略、文档、chunk 和来源路径。资料库后来改名不会改变稳定 ID，历史消息仍可显示发送时名称快照。</p><p>未授权、已删除、不可用或索引未就绪的引用会阻止发送并显示明确原因，不会被当成普通文本忽略。普通消息不会产生 Knowledge 调用。允许研究任务的 Agent 可以显式选择研究模式；系统会显示轮次、证据预算、进度、取消结果和终止原因。</p><h2 id="已移除的阶段性语法" tabindex="-1">已移除的阶段性语法 <a class="header-anchor" href="#已移除的阶段性语法" aria-label="Permalink to &quot;已移除的阶段性语法&quot;">​</a></h2>',11)),o("p",null,[e[1]||(e[1]=l("当前开发周期曾短暂实现 ",-1)),o("code",null,a(d.knowledge),1),e[2]||(e[2]=l(" 和 ",-1)),e[3]||(e[3]=o("code",null,"【knowledge::...】",-1)),e[4]||(e[4]=l(" 检索占位符，但该路径未随正式版本发布，现已移除。预设编辑器、导入导出和上下文处理管道不再生成或解析这些语法。",-1))]),o("p",null,[e[5]||(e[5]=l("Recall 的 ",-1)),o("code",null,a(d.recall),1),e[6]||(e[6]=l(" / ",-1)),e[7]||(e[7]=o("code",null,"【recall::...】",-1)),e[8]||(e[8]=l(" 是独立的思绪召回协议，不代表 Knowledge 仍支持同形占位符。",-1))])])}const A=t(s,[["render",g]]);export{h as __pageData,A as default};
